use std :: path :: { Path , PathBuf } ; use std :: time :: SystemTime ; use anyhow :: { Context , Result } ; use crate :: cli :: LogsArgs ; # [doc = " Spawns `tail` asynchronously, inheriting stdout/stderr."] async fn tail (log_file : & Path , lines : usize , no_follow : bool) -> Result < () > { let mut cmd = tokio :: process :: Command :: new ("tail") ; cmd . arg (format ! ("-n{lines}")) ; if ! no_follow { cmd . arg ("-f") ; } cmd . arg (log_file) ; let status = cmd . status () . await . with_context (| | { format ! ("Failed to run tail on {}. Is `tail` installed?" , log_file . display ()) }) ? ; if ! status . success () { anyhow :: bail ! ("tail exited with status {}" , status . code () . unwrap_or (- 1)) ; } Ok (()) }